<script setup lang="ts">import AppButton from '@/components/AppButton.vue';defineProps<{error?:string;pending?:boolean;busy?:boolean}>();const emit=defineEmits<{recover:[];retry:[];abandon:[]}>()</script>
<template><view v-if="error||pending" class="s1-feedback"><text v-if="error">{{error}}</text><template v-if="pending"><text>本次提交结果待确认，请先回查。原请求重试保持同一内容及操作标识。</text><AppButton variant="secondary" :loading="busy" @click="emit('recover')">回查本次操作</AppButton><AppButton variant="quiet" :disabled="busy" @click="emit('retry')">按原请求重试</AppButton><AppButton variant="quiet" :disabled="busy" @click="emit('abandon')">核实并关闭未提交请求</AppButton></template></view></template>
